<?php

declare(strict_types=1);

namespace Domain\Memory\Calls;

use App\Contracts\CallSender;
use App\Support\CallKey;

/**
 * The signed calls of Memory, generated by php artisan journal:calls; run it again instead of editing.
 */
final readonly class MemoryCalls
{
    public function __construct(private CallSender $sender) {}

    public function editMemory(
        string $memoryId,
        int $revision,
        string|null $text,
        int|null $weight,
        CallKey $requestKey = new CallKey(),
    ): MemoryNamed {
        return $this->sender->send(EditMemoryCall::from([
            'memoryId' => $memoryId,
            'revision' => $revision,
            'text' => $text,
            'weight' => $weight,
            'requestKey' => $requestKey,
        ]));
    }

    public function listMemories(
        int $page = 1,
    ): MemoryPage {
        return $this->sender->send(ListMemoriesCall::from([
            'page' => $page,
        ]));
    }

    public function removeMemory(
        string $memoryId,
        CallKey $requestKey = new CallKey(),
    ): MemoryNamed {
        return $this->sender->send(RemoveMemoryCall::from([
            'memoryId' => $memoryId,
            'requestKey' => $requestKey,
        ]));
    }

    public function saveMemory(
        string $text,
        int $weight,
        CallKey $requestKey = new CallKey(),
    ): MemoryNamed {
        return $this->sender->send(SaveMemoryCall::from([
            'text' => $text,
            'weight' => $weight,
            'requestKey' => $requestKey,
        ]));
    }
}
